Is there an off-by-one in this proration helper?

def prorate_rent(weekly_rent, move_in_day, days_in_month):
    days_left = days_in_month - move_in_day
    daily = weekly_rent * 52 / 12 / days_in_month
    return round(daily * days_left, 2)

print(prorate_rent(500, 10, 30))
